import{body}from'./mesh-data.js';
import{rigMath}from'./render.js';
const{add,sub,mul,dot,cross,unit}=rigMath;
export{body};
const ident=[1,0,0,0,1,0,0,0,1];
export const mv=(r,p)=>[dot(r.slice(0,3),p),dot(r.slice(3,6),p),dot(r.slice(6,9),p)];
const mm=(a,b)=>Array.from({length:9},(_,i)=>a[Math.floor(i/3)*3]*b[i%3]+a[Math.floor(i/3)*3+1]*b[3+i%3]+a[Math.floor(i/3)*3+2]*b[6+i%3]);
export function align(a,b){a=unit(a);b=unit(b);const v=cross(a,b),c=dot(a,b);if(c>.999999)return ident;if(c<-.999999){const u=unit(cross(a,Math.abs(a[0])<.8?[1,0,0]:[0,1,0]));return Array.from({length:9},(_,i)=>2*u[Math.floor(i/3)]*u[i%3]-(i%4===0?1:0));}const K=[0,-v[2],v[1],v[2],0,-v[0],-v[1],v[0],0],KK=mm(K,K);return ident.map((x,i)=>x+K[i]+KK[i]/(1+c));}
export function yawMatrix(a){return[Math.cos(a),0,Math.sin(a),0,1,0,-Math.sin(a),0,Math.cos(a)];}
export function pose({root=[0,0,0],yaw=0,bend=0,headTilt=0,seated=false,folded=false,reach=0,hipY=.56}={}){const Q={},b=bend*Math.PI/180,rot=p=>[p[0],p[1]*Math.cos(b)-p[2]*Math.sin(b),p[1]*Math.sin(b)+p[2]*Math.cos(b)],pel=[0,seated?hipY:.94,0];Q.pelvis=pel;Q.spine=add(pel,rot([0,.18,0]));Q.chest=add(Q.spine,rot([0,.24,0]));Q.neck=add(Q.chest,rot([0,.21,0]));Q.head=add(Q.neck,[0,.15*Math.cos(b+headTilt*Math.PI/180),.15*Math.sin(b+headTilt*Math.PI/180)]);
for(const[side,s]of[['left',-1],['right',1]]){const sh=add(Q.chest,rot([s*.22,.09,0]));Q[side+'Shoulder']=sh;let w=folded?[s*-.12,1.32,.15]:seated?[s*.12,.60+(s>0?reach*.08:0),.36+(s>0?reach*.10:0)]:[s*.26,.93,.035];if(!seated&&!folded)w=add(w,[0,0,0]);const pole=folded?[s*.55,1.1,.22]:seated?[s*.5,.76,.40]:[s*.28,1.15,.15],dir=unit(sub(w,sh)),L1=seated||folded?.304:.28,L2=seated||folded?.26:.24,d=Math.min(L1+L2-.001,Math.hypot(...sub(w,sh))),x=(L1*L1-L2*L2+d*d)/(2*d),h=Math.sqrt(Math.max(0,L1*L1-x*x)),pv=unit(sub(sub(pole,sh),mul(dir,dot(sub(pole,sh),dir)))),el=add(sh,add(mul(dir,x),mul(pv,h)));w=add(sh,mul(dir,d));Q[side+'Elbow']=el;Q[side+'Wrist']=w;const hd=folded?[s*-.9,.05,.3]:seated?[0,-.5,.86]:[s*.15,-.98,.1];Q[side+'Hand']=add(w,mul(unit(hd),.078));Q[side+'Hip']=add(pel,[s*.105,-.02,0]);Q[side+'Knee']=seated?[s*.115,.44,.40]:[s*.115,.51,.015];Q[side+'Ankle']=seated?[s*.115,.095,.44]:[s*.115,.095,0];Q[side+'Foot']=add(Q[side+'Ankle'],[0,-.05,.14]);const handRot=align(sub(body.rest[body.joints.indexOf(side+'Hand')],body.rest[body.joints.indexOf(side+'Wrist')]),hd);for(let f=0;f<5;f++)for(let k=0;k<3;k++){const n=side+'Finger'+f+'_'+k;Q[n]=add(Q[side+'Hand'],mv(handRot,sub(body.rest[body.joints.indexOf(n)],body.rest[body.joints.indexOf(side+'Hand')])));}}
const Y=yawMatrix(yaw);for(const k of Object.keys(Q))Q[k]=add(root,mv(Y,Q[k]));const rotations=body.joints.map((n,i)=>{const par=body.parents[i];return par<0?mm(Y,align([0,1,0],rot([0,1,0]))):mm(align(mv(Y,sub(body.rest[i],body.rest[par])),sub(Q[n],Q[body.joints[par]])),Y)});return{joints:body.joints.map(n=>Q[n]),rotations,named:Q};}
export function skin(p){const v=new Float32Array(body.vertices.length*3),n=new Float32Array(v.length);for(let i=0;i<body.vertices.length;i++){let a=[0,0,0],b=[0,0,0];for(let k=0;k<4;k++){const j=body.skinIndices[i][k],w=body.skinWeights[i][k],R=p.rotations[j],q=add(p.joints[j],mv(R,sub(body.vertices[i],body.rest[j])));a=add(a,mul(q,w));b=add(b,mul(mv(R,body.normals[i]),w));}v.set(a,i*3);n.set(unit(b),i*3);}return{vertices:v,normals:n};}
export function drawBody(scene,p,color){const m=skin(p),V=m.vertices,N=m.normals;for(const f of body.triangles){const a=f.map(i=>Array.from(V.subarray(i*3,i*3+3))),n=f.map(i=>Array.from(N.subarray(i*3,i*3+3)));scene.triangle(...a,color,n);}return m;}
